{
  "tools": [
    {
      "name": "scene_trace",
      "title": "Scene Trace",
      "toolset": "scene",
      "description": "Trace a ray through the active scene's physics and report what it hits - find the floor, check line of sight, probe where something can be placed.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "from": {
            "type": "string",
            "description": "Ray start as 'x,y,z'."
          },
          "to": {
            "type": "string",
            "description": "Ray end as 'x,y,z'."
          }
        },
        "required": [
          "from",
          "to"
        ]
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Hit": {
            "type": "boolean",
            "description": "Whether the trace hit anything."
          },
          "StartedSolid": {
            "type": "boolean",
            "description": "Whether the trace started inside something solid."
          },
          "EndPosition": {
            "type": "string",
            "description": "Where the trace ended - the hit point, or the requested end on a miss."
          },
          "Normal": {
            "type": "string",
            "description": "The hit surface normal."
          },
          "Fraction": {
            "type": "number",
            "description": "How far along the ray the hit was, 0 to 1."
          },
          "Distance": {
            "type": "number",
            "description": "How far the trace travelled, in units."
          },
          "GameObject": {
            "type": "object",
            "properties": {
              "Id": {
                "type": "string"
              },
              "Name": {
                "type": "string"
              }
            },
            "required": [],
            "description": "The game object hit. Null on a miss."
          },
          "Component": {
            "type": "string",
            "description": "The component type hit. Null on a miss."
          }
        },
        "required": []
      }
    }
  ],
  "total": 128
}
